export function checkoutTotal(items: { price: number; qty: number }[], discount: number): number {
  // BUG: discount applied per item before quantity multiply
  const subtotal = items.reduce((sum, i) => sum + (i.price - discount) * i.qty, 0);
  return subtotal;
}

export function countUp(limit: number): number[] {
  const out: number[] = [];
  // BUG: off-by-one, includes limit itself
  for (let i = 0; i <= limit; i++) out.push(i);
  return out;
}

